174→function getMenuForRole(role: string): MenuSection[] {
175→  if (role === "DEAN") return DEAN_MENU;
176→  return ADMIN_MENU; // ADMIN and VIP get the same menu
177→}
178→
179→function filterMenuByResources(
180→  menu: MenuSection[],
181→  viewableResources: string[]
182→): MenuSection[] {
183→  return menu
184→    .map((section) => ({
185→      ...section,
186→      items: section.items.filter((item) =>
187→        viewableResources.includes(item.resource)
188→      ),
189→    }))
190→    .filter((section) => section.items.length > 0);
191→}
192→
193→function isActive(pathname: string, href: string): boolean {
194→  if (href === "/") return pathname === "/";
195→  return pathname === href || pathname.startsWith(href + "/");
196→}
