10→
11→function getStatusBadgeClass(status: string | null): string {
12→  if (!status) return "badge badge-waiting";
13→  if (status.includes("완료")) return "badge badge-complete";
14→  if (status.includes("심사") || status.includes("협의")) return "badge badge-review";
15→  if (status.includes("대기") || !status) return "badge badge-waiting";
16→  return "badge badge-progress";
17→}
18→
19→function parseProgress(progressStr: string | null | number): number {
20→  if (progressStr === null || progressStr === undefined) return 0;
21→  const str = String(progressStr).replace("%", "");
22→  const num = Number.parseInt(str, 10);
23→  return Number.isNaN(num) ? 0 : num;
24→}
25→
26→function getProgressBarColor(progress: number): string {
27→  if (progress >= 100) return "var(--status-complete)";
28→  if (progress >= 50) return "var(--status-progress)";
29→  return "var(--status-review)";
30→}
31→
32→export default function ProgressBoard({ rows, currentUser }: Props) {
33→  // Only show rows that have a requestId (actual recruitment requests)
