 242→function buildStageCells(request: RecruitmentRequest) {
 243→  const stepIndex = getProgressStageIndex(request);
 244→  const procedureType = getProcedureType(request.hiringType);
 245→
 246→  if (procedureType === "정시") {
 247→    const activeBucket =
