 250→      stepIndex === 2 ? "승인" :
 251→      stepIndex <= 7 ? "세부심사" :
 252→      stepIndex === 8 ? "협의" :
 253→      stepIndex === 9 ? "임용준비" :
 254→      "완료";
 255→
 256→    return {
 257→      기획: activeBucket === "기획" ? "action" : stepIndex > 0 ? "done" : "todo",
 258→      요청: activeBucket === "요청" ? "action" : stepIndex > 1 ? "done" : "todo",
 259→      승인: activeBucket === "승인" ? "action" : stepIndex > 2 ? "done" : "todo",
 260→      세부심사: activeBucket === "세부심사" ? "action" : stepIndex > 7 ? "done" : "todo",
 261→      협의: activeBucket === "협의" ? "action" : stepIndex > 8 ? "done" : "todo",
 262→      임용준비: activeBucket === "임용준비" ? "action" : stepIndex > 9 ? "done" : "todo",
 263→      완료: activeBucket === "완료" ? "done" : "todo",
 264→    };
 265→  }
 266→
 267→  const activeBucket =
 268→    stepIndex <= 0 ? "기획" :
 269→    stepIndex <= 2 ? "요청" :
 270→    stepIndex === 3 ? "승인" :
 271→    stepIndex <= 4 ? "세부심사" :
 272→    stepIndex <= 6 ? "협의" :
 273→    stepIndex === 7 ? "임용준비" :
 274→    "완료";
 275→
 276→  return {
 277→    기획: activeBucket === "기획" ? "action" : stepIndex > 0 ? "done" : "todo",
 278→    요청: activeBucket === "요청" ? "action" : stepIndex > 2 ? "done" : "todo",
 279→    승인: activeBucket === "승인" ? "action" : stepIndex > 3 ? "done" : "todo",
 280→    세부심사: activeBucket === "세부심사" ? "action" : stepIndex > 4 ? "done" : "todo",
 281→    협의: activeBucket === "협의" ? "action" : stepIndex > 6 ? "done" : "todo",
 282→    임용준비: activeBucket === "임용준비" ? "action" : stepIndex > 7 ? "done" : "todo",
