 430→export function getDashboardColumns(): DashboardColumn[] {
 431→  const db = getDb();
 432→  const sourceColumns = db
 433→    .prepare(
 434→      `SELECT column_key as key, group_label as groupLabel, column_label as columnLabel, display_order as displayOrder
 435→       FROM dashboard_columns
 436→       ORDER BY display_order ASC`,
 437→    )
 438→    .all() as DashboardColumn[];
 439→
 440→  const transformed: DashboardColumn[] = [];
 441→  let metricsInserted = false;
 442→
 443→  for (const sourceColumn of sourceColumns) {
 444→    if (sourceColumn.key === "소속대학" || sourceColumn.key === "학과명") {
 445→      transformed.push({
 446→        ...sourceColumn,
 447→        groupLabel: normalizeGroupLabel(sourceColumn.key, sourceColumn.groupLabel),
 448→        displayOrder: transformed.length + 1,
 449→      });
 450→      continue;
 451→    }
 452→
 453→    if (!metricsInserted) {
 454→      transformed.push(
 455→        ...EXPANDED_METRIC_COLUMNS.map((column, index) => ({
 456→          ...column,
 457→          displayOrder: transformed.length + index + 1,
 458→        })),
 459→      );
 460→      metricsInserted = true;
 461→    }
 462→
 463→    if (HIDE_COLUMNS.has(sourceColumn.key)) continue;
 464→
 465→    transformed.push({
 466→      ...sourceColumn,
 467→      groupLabel: normalizeGroupLabel(sourceColumn.key, sourceColumn.groupLabel),
 468→      columnLabel: getColumnLabel(sourceColumn.key, sourceColumn.columnLabel),
 469→      displayOrder: transformed.length + 1,
 470→    });
 471→
 472→    if (sourceColumn.key === "(최종) 초빙분야") {
 473→      transformed.push(
 474→        ...PROGRESS_COLUMNS.map((column, index) => ({
 475→          ...column,
 476→          displayOrder: transformed.length + index + 1,
 477→        })),
 478→      );
 479→    }
 480→  }
 481→
 482→  const sorted = transformed.sort((a, b) => {
 483→    const groupDiff = getGroupOrder(a.groupLabel) - getGroupOrder(b.groupLabel);
 484→    if (groupDiff !== 0) return groupDiff;
 485→    return a.displayOrder - b.displayOrder;
 486→  });
 487→
 488→  return sorted.map((column, index) => ({ ...column, displayOrder: index + 1 }));
 489→}
