 986→        r.status as status
 987→      FROM recruitment_requests r
 988→      JOIN departments d ON d.dept_code = r.dept_code
 989→      WHERE r.is_active = 1
 990→      ORDER BY d.college ASC, d.dept_name ASC, CAST(r.priority AS INTEGER) ASC, r.id ASC`,
 991→    )
 992→    .all() as Array<{
 993→    requestId: number;
 994→    college: string;
 995→    deptName: string;
 996→    fieldName: string;
 997→    hiringType: string;
 998→    status: string;
 999→  }>;
1000→
1001→  const submissions = db
1002→    .prepare(
1003→      `SELECT
1004→        id,
1005→        request_id as requestId,
1006→        step_key as stepKey,
1007→        payload_json as payloadJson,
1008→        created_at as createdAt
1009→      FROM submission_data
1010→      ORDER BY created_at DESC, id DESC`,
1011→    )
1012→    .all() as Array<{
1013→    id: number;
1014→    requestId: number;
1015→    stepKey: string;
1016→    payloadJson: string;
1017→    createdAt: string;
1018→  }>;
1019→
1020→  const latestByStep = new Map<string, { id: number; payloadJson: string; createdAt: string }>();
1021→  for (const submission of submissions) {
1022→    const key = `${submission.requestId}:${submission.stepKey}`;
1023→    if (!latestByStep.has(key)) {
1024→      latestByStep.set(key, {
1025→        id: submission.id,
1026→        payloadJson: submission.payloadJson,
1027→        createdAt: submission.createdAt,
1028→      });
1029→    }
1030→  }
1031→
1032→  const rows: AdminWorkflowRow[] = [];
1033→  for (const request of requests) {
