1040→      const submission = latestByStep.get(`${request.requestId}:${step.stepKey}`);
1041→      const payloadJson = submission?.payloadJson ?? JSON.stringify({});
1042→      const payload = JSON.parse(payloadJson) as Record<string, string>;
1043→      const payloadSummary =
1044→        fieldSchema.length > 0
1045→          ? fieldSchema
1046→              .map((field) => `${field.label}: ${String(payload[field.name] ?? "미입력")}`)
1047→              .join("\n")
1048→          : "입력 필드 없음";
1049→
1050→      rows.push({
1051→        requestId: request.requestId,
1052→        college: request.college,
1053→        deptName: request.deptName,
1054→        fieldName: request.fieldName,
1055→        hiringType: request.hiringType,
1056→        currentStatus: request.status,
1057→        stepKey: step.stepKey,
1058→        stepTitle: step.title,
1059→        fieldSchema,
1060→        submissionId: submission?.id ?? null,
1061→        payloadJson,
1062→        payloadSummary,
1063→        createdAt: submission?.createdAt ?? null,
1064→      });
1065→    }
1066→  }
1067→
1068→  return rows;
1069→}
