1488→    return [] as RecruitmentRequestOption[];
1489→  }
1490→
1491→  const db = getDb();
1492→  return db
1493→    .prepare(
1494→      `SELECT
1495→        r.id as requestId,
1496→        r.field_name as fieldName,
1497→        r.hiring_type as hiringType,
1498→        d.dept_name as deptName
1499→      FROM recruitment_requests r
1500→      JOIN departments d ON d.dept_code = r.dept_code
1501→      WHERE r.dept_code = ? AND r.is_active = 1
1502→      ORDER BY
1503→        CASE WHEN r.hiring_type = '상시' THEN 0 ELSE 1 END,
1504→        CAST(r.priority AS INTEGER) ASC,
1505→        r.id ASC`,
1506→    )
1507→    .all(deptCode) as RecruitmentRequestOption[];
1508→}
