1536→export function createRollingRecruitmentRequest(input: {
1537→  deptCode: string;
1538→  fieldName: string;
1539→  hiringReason?: string | null;
1540→  kriFieldName?: string | null;
1541→  deptRequestReason?: string | null;
1542→  notes?: string | null;
1543→}) {
1544→  const db = getDb();
1545→  const nextPriority =
1546→    ((db
1547→      .prepare(
1548→        `SELECT COALESCE(MAX(CAST(priority AS INTEGER)), 0) as maxPriority
1549→         FROM recruitment_requests
1550→         WHERE dept_code = ? AND is_active = 1`,
1551→      )
1552→      .get(input.deptCode) as { maxPriority: number | null } | undefined)?.maxPriority ?? 0) + 1;
1553→
1554→  const result = db
1555→    .prepare(
1556→      `INSERT INTO recruitment_requests (
1557→        dept_code,
