1569→        dept_request_reason,
1570→        notes,
1571→        is_active,
1572→        status,
1573→        next_action,
1574→        raw_json
1575→      ) VALUES (?, 2027, ?, ?, 1, '상시', 0, 0, 0, 0, ?, ?, ?, ?, 1, ?, ?, ?)` ,
1576→    )
1577→    .run(
1578→      input.deptCode,
1579→      String(nextPriority),
1580→      input.fieldName,
1581→      input.hiringReason ?? null,
1582→      input.kriFieldName ?? null,
1583→      input.deptRequestReason ?? null,
1584→      input.notes ?? null,
1585→      getDefaultStatus("상시"),
1586→      getDefaultNextAction("상시"),
1587→      JSON.stringify({
1588→        source: "dean_rolling_creation",
1589→        createdAt: new Date().toISOString(),
1590→      }),
1591→    );
1592→
1593→  return Number(result.lastInsertRowid);
1594→}
